package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math.FieldElement;
import org.apache.commons.math.exception.NotPositiveException;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_divide_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDivide_NormalValues() {
        Complex c = new Complex(10.0, 5.0);
        Complex result = c.divide(2.0);
        Assert.assertEquals(5.0, result.getReal(), DELTA);
        Assert.assertEquals(2.5, result.getImaginary(), DELTA);
    }

    @Test
    public void testDivide_DivisorIsNaN() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.NaN);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_SelfIsNaN() {
        Complex c = new Complex(Double.NaN, 1.0);
        Complex result = c.divide(2.0);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero_And_SelfIsZero() {
        // isZero is true if both real and imaginary are 0
        Complex c = new Complex(0.0, 0.0);
        Complex result = c.divide(0.0);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero_And_SelfIsNotZero() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(0.0);
        Assert.assertTrue(result.isInfinite());
    }

    @Test
    public void testDivide_DivisorIsInfinite_And_SelfIsNotInfinite() {
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        Assert.assertEquals(0.0, result.getReal(), DELTA);
        Assert.assertEquals(0.0, result.getImaginary(), DELTA);
        Assert.assertFalse(result.isNaN());
        Assert.assertFalse(result.isInfinite());
    }

    @Test
    public void testDivide_DivisorIsInfinite_And_SelfIsInfinite() {
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex result = c.divide(Double.POSITIVE_INFINITY);
        Assert.assertTrue(result.isNaN());
    }

    @Test
    public void testDivide_NegativeDivisor() {
        Complex c = new Complex(10.0, -5.0);
        Complex result = c.divide(-2.0);
        Assert.assertEquals(-5.0, result.getReal(), DELTA);
        Assert.assertEquals(2.5, result.getImaginary(), DELTA);
    }
}
